// Run with the isolated configuration generated by check.sh.
import Foundation
@preconcurrency import Network

private enum TestFailure: Error { case failed(String), occupiedPort }
private func check(_ condition: Bool, _ message: String) throws {
    if !condition { throw TestFailure.failed(message) }
}

/// Advance retry time explicitly instead of waiting through production delays.
private actor RetryClock {
    private var pending: [UUID: CheckedContinuation<Void, Error>] = [:]
    private(set) var delays: [TimeInterval] = []
    private(set) var cancellations = 0

    func sleep(_ interval: TimeInterval) async throws {
        let id = UUID()
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                if Task.isCancelled { continuation.resume(throwing: CancellationError()) }
                else {
                    pending[id] = continuation
                    delays.append(interval)
                }
            }
        } onCancel: {
            Task { await self.cancel(id) }
        }
    }

    private func cancel(_ id: UUID) {
        guard let continuation = pending.removeValue(forKey: id) else { return }
        cancellations += 1
        continuation.resume(throwing: CancellationError())
    }

    func advance() {
        let waiting = pending.values
        pending.removeAll()
        waiting.forEach { $0.resume() }
    }
}

@main
struct BridgePolicyTests {
    @MainActor static func main() async throws {
        var backoff = BridgeRetryPolicy()
        let expected: [TimeInterval] = [10, 20, 40, 80, 160, 300, 300, 300]
        let progression = expected.map { _ in backoff.nextDelay(jitter: 1) }
        try check(progression == expected, "Retries must increase to a five-minute cap")
        backoff.reset()
        try check(backoff.nextDelay(jitter: 1) == 10, "Readiness resets the first retry interval")
        for _ in 0..<20 {
            let delay = backoff.nextDelay(jitter: 1.2)
            try check(delay <= 300 && delay >= 8, "Jitter never exceeds the cap")
        }

        let cache = BridgeSnapshotCache()
        var live = MonitorSnapshot.demo
        live.isDemo = false
        let first = await cache.data(for: live)
        try check(first != nil, "The initial live version must encode")
        let fixed = live
        let reads = await withTaskGroup(of: Data?.self) { group in
            for _ in 0..<24 { group.addTask { await cache.data(for: fixed) } }
            var result: [Data?] = []
            for await data in group { result.append(data) }
            return result
        }
        try check(reads.allSatisfy { $0 == first }, "Concurrent requests receive one coherent encoded version")
        try check(await cache.encodingCount == 1, "Unchanged requests must reuse encoded bytes")
        live.error = "Offline"
        let failed = await cache.data(for: live)
        try check(try JSONDecoder().decode(MonitorSnapshot.self, from: failed!) == live,
                  "An error change with the same reading timestamp is published")
        let disconnected = await cache.data(for: .empty)
        try check(try JSONDecoder().decode(MonitorSnapshot.self, from: disconnected!) == .empty,
                  "Disconnect cannot reuse a previous account response")
        try check(await cache.encodingCount == 3, "Only changed versions are encoded")

        let session = BridgeClient.session
        try check(BridgeClient.session === session, "The client retains one process-lifetime session")
        let configuration = session.configuration
        try check(configuration.urlCache == nil && configuration.httpCookieStorage == nil
                  && configuration.urlCredentialStorage == nil && !configuration.httpShouldSetCookies,
                  "Session reuse must preserve the no-cache, no-cookie, no-credential policy")
        try check(configuration.timeoutIntervalForRequest == 5 && configuration.timeoutIntervalForResource == 5
                  && configuration.requestCachePolicy == .reloadIgnoringLocalCacheData
                  && configuration.connectionProxyDictionary?.isEmpty == true,
                  "Session reuse must retain the timeout and direct-connection policy")

        var ready = false
        var actualError: String?
        let serving = BridgeServer()
        serving.start(snapshot: fixed, onError: { error in
            actualError = error
            ready = error == nil
        })
        defer { serving.stop() }
        for _ in 0..<60 {
            if ready { break }
            try await Task.sleep(for: .milliseconds(50))
        }
        try check(ready, "The isolated value-based listener must start: \(actualError ?? "no ready event")")
        let networkReads = try await withThrowingTaskGroup(of: MonitorSnapshot.self) { group in
            for _ in 0..<6 { group.addTask { try await BridgeClient.fetch() } }
            var result: [MonitorSnapshot] = []
            for try await snapshot in group { result.append(snapshot) }
            return result
        }
        try check(networkReads.count == 6 && networkReads.allSatisfy { $0 == fixed },
                  "Concurrent shared-session requests must receive coherent live snapshots")
        serving.update(snapshot: live)
        try check(try await BridgeClient.fetch() == live, "Value publication must expose errors without waiting for a timer")
        serving.update(snapshot: .empty)
        try check(try await BridgeClient.fetch() == .empty, "A fetch after disconnect must see empty account data")

        let contentionClock = RetryClock()
        var recovered = false
        var bindErrors = 0
        let contender = BridgeServer(retrySleep: { try await contentionClock.sleep($0) }, retryJitter: { 1 })
        defer { contender.stop() }
        contender.start(snapshot: fixed, onError: { error in
            if error == nil { recovered = true }
            else { bindErrors += 1 }
        })
        for _ in 0..<60 {
            if await contentionClock.delays.count == 1 { break }
            try await Task.sleep(for: .milliseconds(50))
        }
        let contentionDelays = await contentionClock.delays
        try check(bindErrors == 1 && !recovered && contentionDelays == [10],
                  "A genuinely occupied port must report one error and defer its retry")
        serving.stop()
        await contentionClock.advance()
        for _ in 0..<60 {
            if recovered { break }
            try await Task.sleep(for: .milliseconds(50))
        }
        try check(recovered, "The listener must recover once the competing instance releases its port")
        try check(try await BridgeClient.fetch() == fixed, "Recovered listeners serve the intended snapshot")
        contender.setSuspended(true)
        try check(try await BridgeClient.fetch() == fixed, "Suspension keeps an already-ready local listener available")
        contender.stop()

        let clock = RetryClock()
        var attempts = 0
        var errors = 0
        let server = BridgeServer(retrySleep: { try await clock.sleep($0) }, retryJitter: { 1 }, makeListener: {
            attempts += 1
            throw TestFailure.occupiedPort
        })
        server.start(snapshot: .empty, onError: { if $0 != nil { errors += 1 } })
        for _ in 0..<100 { if await clock.delays.count == 1 { break }; await Task.yield() }
        let initialDelays = await clock.delays
        try check(attempts == 1 && errors == 1 && initialDelays == [10], "A bind failure schedules one bounded retry")
        await clock.advance()
        for _ in 0..<100 { if await clock.delays.count == 2 { break }; await Task.yield() }
        let nextDelays = await clock.delays
        try check(attempts == 2 && nextDelays == [10, 20], "Subsequent failures retain the backoff position")
        server.setSuspended(true)
        for _ in 0..<100 { if await clock.cancellations == 1 { break }; await Task.yield() }
        await clock.advance()
        for _ in 0..<20 { await Task.yield() }
        let suspendedCancellations = await clock.cancellations
        try check(attempts == 2 && suspendedCancellations == 1, "Suspension cancels the retry and prevents a bind attempt")
        server.setSuspended(false)
        for _ in 0..<100 { if await clock.delays.count == 3 { break }; await Task.yield() }
        let resumedDelays = await clock.delays
        try check(attempts == 3 && resumedDelays == [10, 20, 40], "Resume makes one attempt without resetting failure backoff")
        server.stop()
        for _ in 0..<100 { if await clock.cancellations == 2 { break }; await Task.yield() }
        server.setSuspended(true)
        server.setSuspended(false)
        await clock.advance()
        for _ in 0..<20 { await Task.yield() }
        let stoppedCancellations = await clock.cancellations
        try check(attempts == 3 && stoppedCancellations == 2, "Stop cancels retries and resume cannot restart a stopped server")

        print("Bridge policy checks passed: capped retry backoff, cancellation, suspension, coherent encoding cache, shared session safety, concurrent publication, contention recovery.")
    }
}
